import { useEffect, useMemo, useState } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { Link, useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { Search, Filter, ShieldAlert, X, Eye, EyeOff } from 'lucide-react';
import api from '@/api';
import { useAuth } from '@/context/AuthContext';
import { useFeatures } from '@/hooks/useFeatures';
import { prefetchPageForRoute } from '@/pageLoaders';
import DigiShopQuickAction from '@/components/DigiShopQuickAction';
import ReferralBanner from '@/components/ReferralBanner';
import TransactionDetailModal from './TransactionDetailModal';
import TransactionListItem from './TransactionListItem';
import walletReferenceCard from '@/assets/wallet-reference-card.jpg';

const RECENT_TRANSACTIONS_LIMIT = 5;
const OFFICIAL_LOCAL_CURRENCIES = ['CDF', 'USD', 'GMD', 'GNF', 'UGX', 'TZS', 'KES', 'RWF', 'GHS', 'NGN', 'ZAR', 'ZMW', 'EGP'];

export default function DashboardHome() {
  const { t } = useTranslation();
  const nav = useNavigate();
  const { user, refresh } = useAuth();
  const queryClient = useQueryClient();
  const features = useFeatures();
  const { data: txs = [] } = useQuery({
    queryKey: ['dashboard-recent-transactions', user?.id, RECENT_TRANSACTIONS_LIMIT],
    queryFn: async () => {
      const { data } = await api.get('/transactions', {
        params: { limit: RECENT_TRANSACTIONS_LIMIT },
      });
      return Array.isArray(data) ? data.slice(0, RECENT_TRANSACTIONS_LIMIT) : [];
    },
    staleTime: 5_000,
    enabled: Boolean(user?.id),
  });
  const [selectedTx, setSelectedTx] = useState(null);
  const [query, setQuery] = useState('');
  const [showKycBanner, setShowKycBanner] = useState(true);
  const [hidden, setHidden] = useState(() => localStorage.getItem('btp_balance_hidden') === '1');
  const { data: activeCryptoWallets = [], isPending: cryptoWalletsLoading } = useQuery({
    queryKey: ['conversion-crypto-wallets', user?.id],
    queryFn: async () => {
      const { data } = await api.get('/conversion/crypto-wallets');
      return Array.isArray(data) ? data : [];
    },
    staleTime: 10_000,
    enabled: Boolean(user?.id),
  });
  const [selectedCryptoWallet, setSelectedCryptoWallet] = useState('');

  useEffect(() => {
    const refreshDashboard = () => {
      queryClient.invalidateQueries({ queryKey: ['transactions'] });
      queryClient.invalidateQueries({
        queryKey: ['dashboard-recent-transactions', user?.id],
      });
      queryClient.invalidateQueries({
        queryKey: ['conversion-crypto-wallets', user?.id],
      });
      refresh();
    };
    window.addEventListener('btp-wallet-updated', refreshDashboard);
    return () => window.removeEventListener('btp-wallet-updated', refreshDashboard);
  }, [queryClient, refresh, user?.id]);

  const toggleHidden = () => {
    const nv = !hidden;
    setHidden(nv);
    localStorage.setItem('btp_balance_hidden', nv ? '1' : '0');
  };

  const actions = [
    { to: '/dashboard/transfer', image: '/images/transfer-dashboard-icon.webp', label: t('dashboard.transfer'), key: 'transfer' },
    { to: '/dashboard/deposit', image: '/images/deposit-dashboard-icon.webp', label: t('dashboard.deposit'), key: 'deposit' },
    { key: 'digishop' },
    ...(features?.links_enabled !== false
      ? [{ to: '/dashboard/links', image: '/images/link-dashboard-icon.webp', label: t('dashboard.link'), key: 'link' }]
      : []),
    { to: '/dashboard/exchange', image: '/images/exchange-dashboard-icon.webp', label: t('dashboard.exchange'), key: 'exchange' },
  ];
  const actionGridColumns = actions.length === 5 ? 'grid-cols-5' : 'grid-cols-4';

  const needsKyc = user?.kyc_status !== 'verified' && showKycBanner;

  const cryptoWalletOptions = useMemo(
    () => activeCryptoWallets.filter((wallet) => wallet?.id),
    [activeCryptoWallets],
  );
  const highestValueCryptoWallet = useMemo(
    () => cryptoWalletOptions.reduce((best, wallet) => (
      !best
        || Number(wallet.value_usdt ?? wallet.balance ?? 0)
          > Number(best.value_usdt ?? best.balance ?? 0)
        ? wallet
        : best
    ), null),
    [cryptoWalletOptions],
  );
  useEffect(() => {
    if (cryptoWalletOptions.some((wallet) => wallet.id === selectedCryptoWallet)) return;
    setSelectedCryptoWallet(highestValueCryptoWallet?.id || '');
  }, [cryptoWalletOptions, highestValueCryptoWallet, selectedCryptoWallet]);
  const selectedWallet = cryptoWalletOptions.find(
    (wallet) => wallet.id === selectedCryptoWallet,
  );

  const wallets = [
    { key: 'xof', curr: 'XOF', bal: user?.balance_xof ?? 0, gradient: 'from-[#3B82F6] via-[#2563EB] to-[#1D4ED8]', shadow: 'shadow-[0_12px_32px_-12px_rgba(37,99,235,0.45)]' },
    { key: 'xaf', curr: 'XAF', bal: user?.balance_xaf ?? 0, gradient: 'from-[#3B82F6] via-[#2563EB] to-[#1D4ED8]', shadow: 'shadow-[0_12px_32px_-12px_rgba(37,99,235,0.45)]' },
    {
      key: 'crypto',
      curr: selectedWallet?.coin || 'CRYPTO',
      network: selectedWallet?.network_name || selectedWallet?.network
        || (cryptoWalletsLoading ? 'Chargement…' : 'Aucun actif activé'),
      bal: selectedWallet?.balance ?? 0,
      gradient: 'from-emerald-500 via-emerald-600 to-teal-700',
      shadow: 'shadow-[0_12px_32px_-12px_rgba(16,185,129,0.45)]',
    },
    ...OFFICIAL_LOCAL_CURRENCIES
      .map((curr) => ({ key: curr.toLowerCase(), curr, bal: user?.[`balance_${curr.toLowerCase()}`] ?? 0 }))
      .filter((w) => Number.isFinite(Number(w.bal)) && Number(w.bal) !== 0),
  ].filter((w) => !features || features[`wallet_${w.key}_enabled`] !== false);

  const mask = (v) => hidden ? '••••••' : v.toLocaleString(undefined, { maximumFractionDigits: 2 });
  const balanceFontSize = (wallet) => {
    const characterCount = `${mask(wallet.bal)} ${wallet.curr}`.length;
    return `clamp(0.9rem, ${Math.min(24, 165 / characterCount)}cqw, 2.75rem)`;
  };

  return (
    <div className="space-y-4 sm:space-y-6" data-testid="dashboard-home">
      {needsKyc && (
        <div className="relative rounded-xl border border-orange-200 bg-gradient-to-r from-orange-50 to-amber-50 p-3 sm:p-4 flex items-start gap-2.5 sm:gap-3" data-testid="kyc-banner">
          <div className="w-8 h-8 sm:w-10 sm:h-10 rounded-xl bg-orange-500 text-white flex items-center justify-center shrink-0"><ShieldAlert className="w-4 h-4 sm:w-5 sm:h-5" /></div>
          <div className="flex-1 min-w-0">
            <div className="font-cabinet font-bold text-slate-900 text-xs sm:text-sm">{t('dashboard.kyc_banner_title')}</div>
            <p className="mt-0.5 text-[11px] sm:text-xs text-slate-700">{t('dashboard.kyc_banner_body')}</p>
            <Link
              to="/dashboard/kyc"
              onMouseEnter={() => prefetchPageForRoute('/dashboard/kyc')}
              onFocus={() => prefetchPageForRoute('/dashboard/kyc')}
              onTouchStart={() => prefetchPageForRoute('/dashboard/kyc')}
              data-testid="btn-kyc-cta"
              className="mt-2 inline-flex items-center gap-1.5 bg-orange-500 hover:bg-orange-600 text-white font-semibold px-3 sm:px-4 py-1.5 sm:py-2 rounded-full text-[11px] sm:text-xs"
            >
              {t('dashboard.kyc_banner_cta')}
            </Link>
          </div>
          <button onClick={() => setShowKycBanner(false)} className="w-7 h-7 rounded-lg hover:bg-white/70 flex items-center justify-center" data-testid="btn-close-kyc-banner"><X className="w-3.5 h-3.5" /></button>
        </div>
      )}

      {/* Unified wallet card: composition follows the supplied wallet reference. */}
      <section
        data-testid="wallet-balance-card"
        className="relative isolate overflow-hidden rounded-[1.45rem] border border-[#43C5FF]/70 bg-[#0754C9] text-white shadow-[0_22px_48px_-20px_rgba(4,64,173,.7)] sm:rounded-[1.7rem]"
      >
        <div className="relative aspect-[876/345] w-full border-b border-[#39C4FF]/60">
          <img
            src={walletReferenceCard}
            alt="Mon portefeuille Biz-transPay"
            className="absolute inset-0 h-full w-full object-cover object-top"
          />
          <h2 className="sr-only">Mon portefeuille</h2>
          <p className="sr-only">Gérez tous vos soldes en un seul endroit</p>
          <button
            onClick={toggleHidden}
            data-testid="btn-toggle-balance"
            aria-label={hidden ? 'Afficher les soldes' : 'Masquer les soldes'}
            className="absolute right-[2.8%] top-[5%] z-20 flex h-9 w-9 items-center justify-center rounded-full bg-[#1683EE]/95 text-white ring-1 ring-white/30 shadow-md transition-transform hover:scale-105 sm:h-12 sm:w-12"
          >
            {hidden ? <Eye className="h-[17px] w-[17px] sm:h-5 sm:w-5" /> : <EyeOff className="h-[17px] w-[17px] sm:h-5 sm:w-5" />}
          </button>
        </div>

        <div className="relative grid min-h-[6.2rem] grid-cols-3 gap-0 bg-gradient-to-b from-[#0759D2] to-[#0844B5] shadow-[inset_0_1px_0_rgba(255,255,255,.13)] sm:min-h-[8.2rem]">
          {wallets.map((b, index) => (
            <div
              key={b.key}
              data-testid={`balance-card-${b.curr.toLowerCase()}`}
              className={`relative flex min-w-0 items-center justify-center px-1 py-4 sm:px-4 sm:py-5 ${
                index > 0
                  ? 'before:absolute before:bottom-0 before:left-0 before:top-0 before:w-px before:bg-white/25'
                  : ''
              }`}
              style={{ containerType: 'inline-size' }}
            >
              <span className={`absolute left-1/2 top-2 z-10 flex h-6 w-6 -translate-x-1/2 shrink-0 items-center justify-center rounded-full text-[6px] font-extrabold uppercase tracking-[-.04em] shadow-inner ring-1 ring-white/25 sm:top-4 sm:h-10 sm:w-10 sm:text-[8px] ${
                  b.curr === 'XOF'
                    ? 'bg-gradient-to-br from-[#36C1FF] to-[#1470ED]'
                    : b.curr === 'XAF'
                      ? 'bg-gradient-to-br from-[#B15CFF] to-[#7138E8]'
                    : b.curr === 'USDT'
                      ? 'bg-gradient-to-br from-[#32D6A0] to-[#07966F]'
                      : 'bg-gradient-to-br from-[#FFB454] to-[#E66A21]'
                }`}>
                 {b.curr === 'XOF' ? 'FCFA' : b.curr === 'XAF' ? 'CFA' : b.curr}
              </span>
              <div
                data-testid={`balance-value-${b.curr.toLowerCase()}`}
                className="min-w-0 max-w-full overflow-hidden whitespace-nowrap text-center font-extrabold leading-none tracking-[-.055em] text-white"
                style={{ fontSize: balanceFontSize(b) }}
                title={`${mask(b.bal)} ${b.curr}`}
              >
                {mask(b.bal)} <span className="text-[.58em] font-semibold tracking-[-.02em] text-white/80">{b.curr}</span>
              </div>
              {b.key === 'crypto' && (
                <select
                  aria-label="Sélectionner un portefeuille crypto"
                  data-testid="select-dashboard-crypto-wallet"
                  value={selectedWallet?.id || ''}
                  onChange={(event) => setSelectedCryptoWallet(event.target.value)}
                  disabled={!cryptoWalletOptions.length}
                  className="absolute bottom-1.5 left-1/2 z-20 max-w-[92%] -translate-x-1/2 truncate rounded-md border border-white/30 bg-[#0647B6]/90 px-1.5 py-1 text-[8px] font-semibold text-white outline-none transition-colors hover:bg-[#0A65D8] focus-visible:ring-2 focus-visible:ring-white/70 disabled:cursor-not-allowed disabled:opacity-80 sm:bottom-3 sm:px-2 sm:text-[10px]"
                >
                  <option value="" disabled className="text-slate-900">
                    {cryptoWalletsLoading
                      ? 'Chargement…'
                      : cryptoWalletOptions.length ? 'Sélectionner' : 'Aucun actif activé'}
                  </option>
                  {cryptoWalletOptions.map((wallet) => (
                    <option key={wallet.id} value={wallet.id} className="text-slate-900">
                      {wallet.coin} · {wallet.network_name || wallet.network}
                    </option>
                  ))}
                </select>
              )}
            </div>
          ))}
        </div>
      </section>

      {/* Quick actions */}
      <div className="bg-white border border-slate-100 rounded-2xl p-3 sm:p-5 shadow-[0_2px_12px_rgba(15,23,42,0.03)]">
        <div className={`grid ${actionGridColumns} gap-2 sm:gap-3`}>
          {actions.map((a) => a.key === 'digishop' ? (
            <DigiShopQuickAction key={a.key} />
          ) : (
            <button
              key={a.key}
              onClick={() => nav(a.to)}
              onMouseEnter={() => prefetchPageForRoute(a.to)}
              onFocus={() => prefetchPageForRoute(a.to)}
              onTouchStart={() => prefetchPageForRoute(a.to)}
              data-testid={`quick-action-${a.key}`}
              className="group flex flex-col items-center gap-1.5 py-2.5 rounded-xl transition-colors hover:bg-slate-50 active:scale-95 sm:gap-2 sm:py-3"
            >
              <div className="w-10 h-10 sm:w-12 sm:h-12 overflow-hidden rounded-full ring-1 ring-slate-200/70 transition-transform group-hover:scale-105">
                <img src={a.image} alt="" aria-hidden="true" className="h-full w-full object-cover" decoding="async" />
              </div>
              <div className="font-cabinet font-bold text-slate-900 text-[10px] sm:text-xs">{a.label}</div>
            </button>
          ))}
        </div>
      </div>

      <ReferralBanner />

      {/* Search */}
      <div className="bg-white border border-slate-100 rounded-2xl p-2.5 sm:p-3 flex items-center gap-2 sm:gap-3 shadow-[0_4px_20px_rgba(15,23,42,0.04)]">
        <Search className="w-4 h-4 sm:w-5 sm:h-5 text-slate-400 ml-2 sm:ml-3" />
        <input
          data-testid="dashboard-search"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && nav(`/dashboard/transactions?q=${encodeURIComponent(query.trim())}`)}
          placeholder={t('dashboard.search_ph')}
          className="flex-1 py-2 sm:py-2.5 outline-none text-xs sm:text-sm bg-transparent"
        />
        <button data-testid="btn-filter" className="w-8 h-8 sm:w-10 sm:h-10 rounded-xl hover:bg-slate-100 flex items-center justify-center">
          <Filter className="w-3.5 h-3.5 sm:w-4 sm:h-4 text-slate-600" />
        </button>
      </div>

      {/* Recent transactions */}
      <div className="bg-white border border-slate-100 rounded-2xl shadow-[0_4px_20px_rgba(15,23,42,0.04)]">
        <div className="p-4 sm:p-6 flex items-center justify-between border-b border-slate-100">
          <h3 className="font-cabinet font-bold text-slate-900 text-sm sm:text-lg">{t('dashboard.recent_activity')}</h3>
          <Link
            to="/dashboard/transactions"
            onMouseEnter={() => prefetchPageForRoute('/dashboard/transactions')}
            onFocus={() => prefetchPageForRoute('/dashboard/transactions')}
            onTouchStart={() => prefetchPageForRoute('/dashboard/transactions')}
            className="text-xs sm:text-sm font-semibold text-[#2563EB] hover:text-[#1D4ED8]"
            data-testid="link-all-tx"
          >
            {t('hero.see_all')} →
          </Link>
        </div>
        <div className="divide-y divide-slate-50">
          {txs.length === 0 && <div className="p-8 sm:p-10 text-center text-slate-400 text-xs sm:text-sm">{t('dashboard.no_tx')}</div>}
          {txs.map((tx) => (
            <TransactionListItem
              key={tx.id}
              tx={tx}
              hidden={hidden}
              onClick={() => setSelectedTx(tx)}
              testId={`home-tx-row-${tx.id}`}
            />
          ))}
        </div>
      </div>
      {selectedTx && <TransactionDetailModal tx={selectedTx} onClose={() => setSelectedTx(null)} />}
    </div>
  );
}
